sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    // Update the incident watch list. NB it is update_multiple data resource
    let query = api.state.selected_incidents;
    let manager = api.data.Group_Manager.results[0].manager._reference.sys_id.value;

    api.data.update_multiple_incidents.execute({
        table: "incident",
        query: query,
        templateFields: "watch_list=" + manager
    });

    // Show alert before refresh of the grid
    api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
        items: [{
            id: "incident-updated",
            status: "info",
            icon: "circle-check-outline",
            content: {
                type: "html",
                value: "<h4>" + "Manager is added to the selected incident records." + "<h4>"
            },
            action: {
                type: "dismiss"
            },
        }]
    });

    // refresh the grid after update of the watchlist
    api.setState('refresh_list', {timestamp: Date.now()});


}
